"use client";

import { type HTMLAttributes, useId, useState } from "react";
import { cx } from "../utils/cx";

export type RatingProps = Omit<HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> & {
  /** Names the rating (e.g. "Rate this gallery"). */
  "aria-label": string;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  max?: number;
  /** Display only. Fractional values draw a partly filled star. */
  readOnly?: boolean;
  size?: "sm" | "md" | "lg";
};

const STAR = "M8 1.7l1.85 4.05 4.45.5-3.3 3.05.9 4.4L8 11.5l-3.9 2.2.9-4.4L1.7 6.25l4.45-.5z";

/**
 * A star rating on native radio inputs, so arrow keys, a single tab stop and form posting come for free. Hovering
 * previews the rating and the stars fill with a small spring. `readOnly` shows any value, including halves.
 */
export function Rating({
  value: controlled,
  defaultValue = 0,
  onValueChange,
  max = 5,
  readOnly,
  size = "md",
  className,
  ...rest
}: RatingProps) {
  const [inner, setInner] = useState(defaultValue);
  const value = controlled ?? inner;
  const [hover, setHover] = useState<number | null>(null);
  const name = useId();
  const shown = hover ?? value;
  if (readOnly) {
    return (
      <div
        {...rest}
        role="img"
        aria-label={`${rest["aria-label"]}: ${value} out of ${max}`}
        className={cx("hm-rating", className)}
        data-size={size}
        data-readonly=""
      >
        {Array.from({ length: max }, (_, i) => {
          const fill = Math.max(0, Math.min(1, value - i));
          return (
            <span key={i} className="hm-star" style={{ "--_fill": `${fill * 100}%` } as React.CSSProperties}>
              <Star />
            </span>
          );
        })}
      </div>
    );
  }
  return (
    <div
      {...rest}
      role="radiogroup"
      className={cx("hm-rating", className)}
      data-size={size}
      onPointerLeave={() => setHover(null)}
    >
      {Array.from({ length: max }, (_, i) => {
        const n = i + 1;
        return (
          <label
            key={n}
            className="hm-star"
            data-on={n <= shown ? "" : undefined}
            style={{ "--_fill": n <= shown ? "100%" : "0%" } as React.CSSProperties}
            onPointerEnter={() => setHover(n)}
          >
            <input
              className="hm-rating-input"
              type="radio"
              name={name}
              value={n}
              checked={Math.round(value) === n}
              aria-label={`${n} ${n === 1 ? "star" : "stars"}`}
              onChange={() => {
                if (controlled === undefined) setInner(n);
                onValueChange?.(n);
              }}
            />
            <Star />
          </label>
        );
      })}
    </div>
  );
}

function Star() {
  return (
    <svg viewBox="0 0 16 16" aria-hidden="true">
      <path className="hm-star-back" d={STAR} />
      <path className="hm-star-front" d={STAR} />
    </svg>
  );
}
